package com.notesshared.servlet;
import com.notesshared.util.Db;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/registration-data") public class RegistrationDataServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("application/json;charset=UTF-8");try(Connection c=Db.getConnection()){String id=r.getParameter("collegeId");if(id==null||id.isBlank()){try(PreparedStatement p=c.prepareStatement("SELECT id,name FROM colleges ORDER BY name");ResultSet q=p.executeQuery()){StringBuilder j=new StringBuilder("{\"colleges\":[");boolean f=true;while(q.next()){if(!f)j.append(',');f=false;j.append("{\"id\":").append(q.getInt(1)).append(",\"name\":\"").append(esc(q.getString(2))).append("\"}");}s.getWriter().print(j.append("]}"));}}else{try{int cid=Integer.parseInt(id);try(PreparedStatement p=c.prepareStatement("SELECT id,code,name FROM courses WHERE college_id=? ORDER BY name")){p.setInt(1,cid);try(ResultSet q=p.executeQuery()){StringBuilder j=new StringBuilder("{\"courses\":[");boolean f=true;while(q.next()){if(!f)j.append(',');f=false;j.append("{\"id\":").append(q.getInt(1)).append(",\"label\":\"").append(esc(q.getString(2)+" - "+q.getString(3))).append("\"}");}s.getWriter().print(j.append("]}"));}}}catch(NumberFormatException ex){s.getWriter().print("{\"courses\":[]}");}}}catch(SQLException e){s.setStatus(500);s.getWriter().print("{\"error\":\"Database error\"}");}}
private String esc(String x){return x.replace("\\","\\\\").replace("\"","\\\"").replace("\r","\\r").replace("\n","\\n");}}
